//    - below 0.3: expect 3,000; sd = sqrt(10000 x 0.3 x 0.7) = 45.8;
//      3 sd -> 2,863 to 3,137.
//    - mean: expect 0.5; sd = sqrt(1/12 / 10000) = 0.00289; 3 sd -> 0.4913 to 0.5087.
{
