  checkClose("seed 1, 2nd number matches Python", rand(), 0.002735721180215478);
  checkClose("seed 1, 3rd number matches Python", rand(), 0.5274470399599522);
  checkClose("seed 0, 1st number matches Python", makeRng(0)(), 0.26642920868471265);
  checkClose("seed 42, 1st number matches Python", makeRng(42)(), 0.6011037519201636);
}

