check("N = 0 cells: no cancer (null)", simulatePerson(0, 4, 1, makeRng(1)), null);

// 2. p = 1: every cell gains a hit every year (ages 0, 1, 2, ...), so the
//    r-th hit comes at age r - 1. The spec's hand check: r = 3 -> age 2.
