{
  const rand = makeRng(32);
  const ages = Array.from({ length: 10000 }, () => simulatePerson(10, 1, 0.1, rand));
  checkBetween("10 cells: about 6,513 cancers at age 0", ages.filter((a) => a === 0).length, 6370, 6656);
}

