console.log("makeRng");

// 1. It is really mulberry32: matches a separate Python version (plain
//    arithmetic mod 2^32 instead of JavaScript's bit tricks), several seeds,
//    so a hardcoded answer could not pass.
{
  const rand = makeRng(1);
