//    By hand: 0.7 miss -> 0; 0.2 hit -> 1; 0.9 miss -> 1; 0.1 hit -> 2; 0.4 hit -> 3.
{
  const rand = fakeRand([0.7, 0.2, 0.9, 0.1, 0.4]);
