//    By hand: expect 2,000 hits; sd = sqrt(10000 x 0.2 x 0.8) = 40;
//    3 sd -> 1,880 to 2,120.
{
  const rand = makeRng(22);
  let count = 0;
  for (let i = 0; i < 10000; i++) count += stepCell(0, 4, 0.2, rand);
