checkThrows("seed -1 (negative) throws", () => makeRng(-1));
checkThrows("seed 4294967296 (too big) throws", () => makeRng(4294967296));
checkThrows('seed "1" (text) throws', () => makeRng("1"));
checkThrows("no seed throws", () => makeRng());

