  const rand = sfc32Rng(seed), counts = [0, 0, 0, 0, 0];
  for (let c = 0; c < n; c++) { let h = 0; for (let a = 0; a < 85; a++) h = stepCell(h, 4, p, rand); counts[h]++; }
